// Every role of a desktop's theme (docs/jsx-ui.md "Themes"), each with its
// name under it. Each element gives its role with `look` and keeps its own
// classes, FrameOS's look: in a desktop window the desktop's theme takes their
// place, full screen they show. Live where they can be: the buttons press, the
// day picks, the field types, the options and tiles pick, the switch toggles,
// a key lights. What you changed is the private `gallery` field.

const STATE = 'gallery'

function stateOf(app) {
  const kept = app.state[STATE]
  if (kept && typeof kept === 'object') return kept
  if (typeof kept === 'string' && kept) {
    try {
      return JSON.parse(kept) || {}
    } catch (e) {
      return {}
    }
  }
  return {}
}

// FrameOS's own look for each role, and a high-contrast one for e-paper and
// grey panels: what an element shows where no desktop gives a theme.
function ownLook(app) {
  const ink = app.frame.paper === true || app.frame.color === false
  if (ink) {
    return {
      page: 'bg-white text-black',
      bar: 'border-b-2 border-black',
      button: 'rounded-full border-2 border-black',
      primary: 'rounded-full bg-black text-white font-bold',
      selected: 'rounded-full bg-black text-white',
      field: 'rounded-lg border-2 border-black',
      option: 'rounded-lg',
      picked: 'rounded-lg bg-black text-white',
      switch: 'rounded-full border-2 border-black',
      switchOn: 'rounded-full border-2 border-black',
      knob: 'rounded-full border-2 border-black',
      knobOn: 'rounded-full bg-black',
      muted: '',
      accent: 'bg-black',
      card: 'rounded-lg border-2 border-black',
      tile: 'rounded-xl border-2 border-black',
      tileLit: 'rounded-xl border-2 border-black bg-black text-white',
      keyboard: 'bg-white text-black border-t-2 border-black',
      key: 'rounded-md border-2 border-black',
      keyMod: 'rounded-md border-2 border-black bg-black text-white',
      keyLit: 'rounded-md bg-black text-white',
    }
  }
  return {
    page: 'bg-zinc-950 text-white',
    bar: 'border-b border-zinc-800',
    button: 'rounded-full bg-zinc-800 active:bg-zinc-600',
    primary: 'rounded-full bg-sky-600 active:bg-sky-500 font-bold',
    selected: 'rounded-full bg-sky-600',
    field: 'rounded-lg bg-zinc-800 focus:bg-zinc-700 placeholder:text-zinc-500',
    option: 'rounded-lg active:bg-zinc-600',
    picked: 'rounded-lg bg-sky-600',
    switch: 'rounded-full bg-zinc-700',
    switchOn: 'rounded-full bg-sky-500',
    knob: 'rounded-full bg-white',
    knobOn: 'rounded-full bg-white',
    muted: 'text-zinc-400',
    accent: 'bg-sky-500',
    card: 'rounded-lg bg-zinc-900',
    tile: 'rounded-xl border-2 border-zinc-800 bg-zinc-800 active:bg-zinc-700',
    tileLit: 'rounded-xl border-2 border-sky-400 bg-zinc-800',
    keyboard: 'bg-zinc-900 text-white',
    key: 'rounded-md bg-zinc-700 active:bg-zinc-500',
    keyMod: 'rounded-md bg-zinc-800 active:bg-zinc-600',
    keyLit: 'rounded-md bg-zinc-500',
  }
}

// A role's name, under or beside what shows it, in the quieter text.
let quiet = ''
const Name = ({ children }) => (
  <span look="muted" className={`text-[11px] leading-none font-mono whitespace-nowrap ${quiet}`}>
    {children}
  </span>
)

const Section = ({ title, children }) => (
  <div className="flex flex-col gap-[8px]">
    <span className="text-[13px] font-bold uppercase">{title}</span>
    {children}
  </div>
)

// An element and its role's name under it.
const Named = ({ name, children }) => (
  <div className="flex flex-col items-start gap-[4px]">
    {children}
    <Name>{name}</Name>
  </div>
)

// On a round panel (only the circle inside the square shows) the page is
// laid out in the square inside that circle, 12 px in from the rim, and
// scrolls there.
export function get(app, context) {
  if (!context || context.round !== true) return getPage(app, context)
  const W = context.imageWidth, H = context.imageHeight
  const side = Math.floor((Math.min(W, H) / 2 - 12) * Math.SQRT2)
  return (
    <div look="page" className={`relative w-[${W}px] h-[${H}px] ${ownLook(app).page}`}>
      <div className={`absolute left-[${(W - side) >> 1}px] top-[${(H - side) >> 1}px] w-[${side}px] h-[${side}px]`}>
        {getPage(app, { ...context, imageWidth: side, imageHeight: side })}
      </div>
    </div>
  )
}

function getPage(app, context) {
  const own = ownLook(app)
  quiet = own.muted
  const s = stateOf(app)
  const set = (change) => frameos.setState(STATE, { ...stateOf(app), ...change })
  const width = (context && context.imageWidth) || app.frame.width
  const wide = width >= 640
  const presses = s.presses || 0
  const saves = s.saves || 0
  const day = s.day || 'Day'
  const picked = s.picked || 'Pears'
  const on = s.on === true
  const lit = s.tile || 'Two'
  const key = s.key || 'r'

  const button = 'flex items-center h-[34px] px-[16px] text-[14px]'

  const buttons = (
    <Section title="Buttons">
      <div className="flex flex-wrap items-start gap-[10px]">
        <Named name="button">
          <div look="button" className={`${button} ${own.button}`} onClick={() => set({ presses: presses + 1 })}>
            Press
          </div>
        </Named>
        <Named name="primary">
          <div look="primary" className={`${button} ${own.primary}`} onClick={() => set({ saves: saves + 1 })}>
            Save
          </div>
        </Named>
      </div>
      <span look="muted" className={`text-[12px] ${own.muted}`}>{`Pressed ${presses}, saved ${saves}`}</span>
      <div className="flex items-start gap-[6px]">
        {['Day', 'Week', 'Month'].map((name) => (
          <Named name={name === day ? 'selected' : 'button'}>
            <div
              look={name === day ? 'selected' : 'button'}
              className={`${button} ${name === day ? own.selected : own.button}`}
              onClick={() => set({ day: name })}
            >
              {name}
            </div>
          </Named>
        ))}
      </div>
    </Section>
  )

  const field = (
    <Section title="Field">
      <Named name="field">
        <input
          look="field"
          className={`w-[220px] h-[34px] px-[10px] text-[14px] ${own.field}`}
          value={s.text || ''}
          placeholder="Type here"
          onChange={(e) => set({ text: e.target.value })}
        />
      </Named>
    </Section>
  )

  const options = (
    <Section title="Options">
      <div className="flex flex-col gap-[2px] w-[220px]">
        {['Apples', 'Pears', 'Plums'].map((name) => (
          <div
            look={name === picked ? 'picked' : 'option'}
            className={`flex items-center justify-between h-[32px] px-[10px] text-[14px] ${name === picked ? own.picked : own.option}`}
            onClick={() => set({ picked: name })}
          >
            <span>{name}</span>
            {name === picked ? (
              // The picked row's own text color: a quieter one may not show on it.
              <span className="text-[11px] leading-none font-mono">picked</span>
            ) : (
              <Name>option</Name>
            )}
          </div>
        ))}
      </div>
    </Section>
  )

  const toggle = (
    <Section title="Switch">
      <div className="flex items-center gap-[12px]" onClick={() => set({ on: !on })}>
        <div
          look={on ? 'switchOn' : 'switch'}
          className={`flex w-[52px] h-[30px] p-[3px] shrink-0 ${on ? 'justify-end' : ''} ${on ? own.switchOn : own.switch}`}
        >
          <div look={on ? 'knobOn' : 'knob'} className={`h-full aspect-square ${on ? own.knobOn : own.knob}`} />
        </div>
        <Name>{on ? 'switchOn, knobOn' : 'switch, knob'}</Name>
      </div>
    </Section>
  )

  const text = (
    <Section title="Text">
      <div className="flex flex-col gap-[6px]">
        <span className="text-[14px]">The page's own text</span>
        <Named name="muted">
          <span look="muted" className={`text-[14px] ${own.muted}`}>
            Quieter text
          </span>
        </Named>
        <div className="flex items-center gap-[8px]">
          <div look="accent" className={`w-[12px] h-[12px] rounded-full shrink-0 ${own.accent}`} />
          <Name>accent</Name>
        </div>
      </div>
    </Section>
  )

  const card = (
    <Section title="Card">
      <Named name="card">
        <div look="card" className={`flex flex-col gap-[4px] p-[10px] w-[240px] ${own.card}`}>
          <div className="flex gap-[10px] text-[13px]">
            <span look="muted" className={own.muted}>
              Theme
            </span>
            <span>{app.frame.theme ? "The desktop's" : 'None: each element its own'}</span>
          </div>
          <div className="flex gap-[10px] text-[13px]">
            <span look="muted" className={own.muted}>
              Roles
            </span>
            <span>{app.frame.theme ? `${Object.keys(app.frame.theme).length} given` : '21 in all'}</span>
          </div>
        </div>
      </Named>
    </Section>
  )

  const tiles = (
    <Section title="Tiles">
      <div className="flex gap-[8px]">
        {['One', 'Two', 'Three'].map((name) => (
          <div className="flex flex-col items-center gap-[4px]">
            <div
              look={name === lit ? 'tileLit' : 'tile'}
              className={`flex items-center justify-center w-[64px] h-[48px] text-[13px] ${name === lit ? own.tileLit : own.tile}`}
              onClick={() => set({ tile: name })}
            >
              {name}
            </div>
            <Name>{name === lit ? 'tileLit' : 'tile'}</Name>
          </div>
        ))}
      </div>
    </Section>
  )

  const keyCap = (label, role, onTap) => (
    <div
      look={role}
      className={`flex items-center justify-center h-[34px] ${label.length > 1 ? 'w-[48px]' : 'w-[32px]'} text-[14px] ${own[role]}`}
      onClick={onTap}
    >
      {label}
    </div>
  )
  const keyboard = (
    <Section title="Keyboard">
      <div look="keyboard" className={`flex flex-col gap-[6px] p-[8px] w-[280px] ${own.keyboard}`}>
        <div className="flex gap-[5px]">
          {keyCap('shift', 'keyMod')}
          {['q', 'w', 'e', 'r', 't'].map((letter) => keyCap(letter, letter === key ? 'keyLit' : 'key', () => set({ key: letter })))}
        </div>
      </div>
      <div className="flex flex-wrap gap-x-[10px] gap-y-[4px]">
        <Name>keyboard</Name>
        <Name>keyMod: shift</Name>
        <Name>{`keyLit: ${key}`}</Name>
        <Name>key: the rest</Name>
      </div>
    </Section>
  )

  const left = [buttons, field, options, toggle]
  const right = [text, card, tiles, keyboard]
  return (
    <div look="page" className={`flex flex-col w-full h-full ${own.page}`}>
      <div look="bar" className={`flex items-center gap-[10px] h-[48px] px-[16px] shrink-0 ${own.bar}`}>
        <span className="text-[17px] font-bold">Theme roles</span>
        {/* Where the bar has no room for it, the line goes over the page. */}
        {width >= 480 ? (
          <span look="muted" className={`flex-1 min-w-0 truncate text-[12px] ${own.muted}`}>
            Each role of the desktop's theme, by name
          </span>
        ) : (
          <span className="flex-1" />
        )}
        <Name>page, bar</Name>
      </div>
      <div className="flex-1 min-h-0 overflow-y-auto">
        {width >= 480 ? null : (
          <div look="muted" className={`px-[16px] pt-[12px] text-[12px] ${own.muted}`}>Each role of the desktop's theme, by name</div>
        )}
        {wide ? (
          <div className="flex gap-[28px] p-[16px]">
            <div className="flex flex-col gap-[18px] flex-1 min-w-0">{left}</div>
            <div className="flex flex-col gap-[18px] flex-1 min-w-0">{right}</div>
          </div>
        ) : (
          <div className="flex flex-col gap-[18px] p-[16px]">{left.concat(right)}</div>
        )}
      </div>
    </div>
  )
}
